import * as React from "react";

import { FrameScope, useInFrame } from "../lib/frame-context";
import { CipherLink, type CipherLinkTarget } from "../lib/link";
import { cn } from "../lib/utils";
import { Checkbox } from "./checkbox";
import { Skeleton } from "./skeleton";

import styles from "./data.module.css";
import frame from "./frame.module.css";

interface ListContextValue {
  selected: readonly string[];
  multiple: boolean;
  size: "md" | "sm";
  actionsPlacement: "end" | "below";
  toggle: (id: string) => void;
}
const ListContext = React.createContext<ListContextValue | null>(null);
export interface ListRowProps {
  value: string;
  title: React.ReactNode;
  description?: React.ReactNode;
  media?: React.ReactNode;
  badge?: React.ReactNode;
  meta?: React.ReactNode;
  actions?: React.ReactNode;
  error?: React.ReactNode;
  children?: React.ReactNode;
  href?: string;
  /** A router link (to, params, search); the title renders as one anchor that keeps modifier clicks native. */
  link?: CipherLinkTarget;
  onClick?: (event: React.MouseEvent) => void;
  current?: boolean;
  disabled?: boolean;
  selectable?: boolean;
  unread?: boolean;
  resolved?: boolean;
  label: string;
}
export function ListRow({
  value,
  title,
  description,
  media,
  badge,
  meta,
  actions,
  error,
  children,
  href,
  link,
  onClick,
  current,
  disabled,
  selectable = true,
  unread,
  resolved,
  label
}: ListRowProps) {
  const context = React.useContext(ListContext);
  const fullTitle = typeof title === "string" ? title : undefined;
  const checked = context?.selected.includes(value);
  const anchor = Boolean(href || link);
  const button = !anchor && (onClick || (context?.multiple && selectable));
  const click = (event: React.MouseEvent) => {
    if (disabled) {
      event.preventDefault();
      return;
    }
    if (onClick) onClick(event);
    else if (context?.multiple && selectable) context.toggle(value);
  };
  let disabledRole: "button" | "link" | undefined;
  if (disabled && anchor) disabledRole = "link";
  else if (disabled && button) disabledRole = "button";
  const below = context?.actionsPlacement === "below" && context.size !== "sm";
  const [pressed, setPressed] = React.useState(false);
  React.useEffect(() => {
    if (!pressed) return undefined;
    const release = () => setPressed(false);
    window.addEventListener("pointerup", release);
    window.addEventListener("pointercancel", release);
    window.addEventListener("keyup", release);
    window.addEventListener("blur", release);
    return () => {
      window.removeEventListener("pointerup", release);
      window.removeEventListener("pointercancel", release);
      window.removeEventListener("keyup", release);
      window.removeEventListener("blur", release);
    };
  }, [pressed]);
  const press = {
    onPointerDown: (event: React.PointerEvent) => {
      if (event.button === 0) setPressed(true);
    }
  };
  return (
    <li
      className={styles.listRow}
      data-list-row={value}
      data-selected={checked || undefined}
      data-current={current || undefined}
      data-disabled={disabled || undefined}
      data-resolved={resolved || undefined}
      data-size={context?.size}
      data-interactive={(!disabled && Boolean(anchor || button)) || undefined}
      data-pressed={pressed || undefined}
    >
      {context?.multiple && (
        <span className={styles.rowCheck}>
          <Checkbox
            aria-label={`Select ${label}`}
            checked={checked}
            disabled={disabled || !selectable}
            onCheckedChange={() => context.toggle(value)}
          />
        </span>
      )}
      {media && (
        <span className={styles.rowMedia}>
          {media}
          {unread && <span className={styles.unread} aria-hidden />}
        </span>
      )}
      {unread && <span className={styles.sr}>Unread</span>}
      <div className={styles.listBody}>
        <div className={styles.titleLine}>
          {unread && !media && <span className={styles.unread} aria-hidden />}
          {link && !disabled ? (
            <CipherLink
              link={link}
              className={styles.rowTitle}
              title={fullTitle}
              onClick={click}
              {...press}
              aria-current={current ? "page" : undefined}
              data-list-target
            >
              {title}
            </CipherLink>
          ) : href && !disabled ? (
            <a
              className={styles.rowTitle}
              title={fullTitle}
              href={href}
              onClick={click}
              {...press}
              aria-current={current ? "page" : undefined}
              data-list-target
            >
              {title}
            </a>
          ) : button && !disabled ? (
            <button
              type="button"
              className={styles.rowTitle}
              title={fullTitle}
              onClick={click}
              {...press}
              onKeyDown={(event) => {
                if (event.key === " ") setPressed(true);
              }}
              aria-current={current ? "true" : undefined}
              data-list-target
            >
              {title}
            </button>
          ) : (
            <span
              className={styles.rowTitle}
              title={fullTitle}
              role={disabledRole}
              aria-disabled={disabledRole ? true : undefined}
            >
              {title}
            </span>
          )}
          {badge && <span className={styles.rowBadge}>{badge}</span>}
          {meta && <span className={styles.rowMeta}>{meta}</span>}
        </div>
        {description && context?.size !== "sm" && (
          <p className={styles.description}>{description}</p>
        )}
        {error && (
          <div className={styles.rowError} role="alert">
            {error}
          </div>
        )}
        {children}
        {below && actions && <div className={styles.rowActions}>{actions}</div>}
      </div>
      {!below && actions && <div className={styles.rowActions}>{actions}</div>}
    </li>
  );
}
function rowProps(children: React.ReactNode): ListRowProps[] {
  return React.Children.toArray(children).flatMap((child) => {
    if (!React.isValidElement<ListRowProps & { children?: React.ReactNode }>(child)) return [];
    if (child.type === ListRow) return [child.props];
    return rowProps(child.props.children);
  });
}
export interface ListHeaderProps {
  title?: React.ReactNode;
  count?: React.ReactNode;
  action?: React.ReactNode;
}
export const ListHeader: React.FC<ListHeaderProps> = () => null;
/** State that must stay visible under the rows, never an action result; those go to a toast. */
export const ListFooter: React.FC<{ children: React.ReactNode }> = () => null;
export interface ListProps extends ListHeaderProps {
  children?: React.ReactNode;
  label: string;
  variant?: "framed" | "plain" | "bare" | "segmented" | "divided";
  size?: "md" | "sm";
  actionsPlacement?: "end" | "below";
  selection?: "none" | "multiple";
  selectedIds?: readonly string[];
  defaultSelectedIds?: readonly string[];
  onSelectionChange?: (ids: string[]) => void;
  loading?: boolean;
  loadingRows?: number;
  empty?: React.ReactNode;
  /** State that must stay visible under the rows, never an action result; those go to a toast. */
  footer?: React.ReactNode;
}
export function List({
  children: content,
  title: titleProp,
  count: countProp,
  action: actionProp,
  label,
  variant: requestedVariant,
  size = "md",
  actionsPlacement = "end",
  selection = "none",
  selectedIds,
  defaultSelectedIds = [],
  onSelectionChange,
  loading,
  loadingRows = 3,
  empty = "No items",
  footer: footerProp
}: ListProps) {
  let header: ListHeaderProps = { title: titleProp, count: countProp, action: actionProp };
  let footer = footerProp;
  let children = content;
  const parts = React.Children.toArray(content);
  if (
    parts.some(
      (part) => React.isValidElement(part) && (part.type === ListHeader || part.type === ListFooter)
    )
  ) {
    children = parts.filter((part) => {
      if (!React.isValidElement(part)) return true;
      if (part.type === ListHeader) header = part.props as ListHeaderProps;
      else if (part.type === ListFooter)
        footer = (part.props as { children: React.ReactNode }).children;
      else return true;
      return false;
    });
  }
  const { title, count: headerCount, action } = header;
  const variant = requestedVariant ?? "framed";
  const inFrame = useInFrame("List", requestedVariant);
  const embedded = inFrame && variant === "framed";
  const framed = variant === "framed" && !embedded;
  const [own, setOwn] = React.useState<readonly string[]>(defaultSelectedIds);
  const selected = selectedIds ?? own;
  const list = React.useRef<HTMLUListElement>(null);
  const focusedRow = React.useRef<{ element: HTMLElement; index: number } | null>(null);
  React.useLayoutEffect(() => {
    const previous = focusedRow.current;
    const container = list.current;
    if (!previous || !container) return;
    const targets = Array.from(container.querySelectorAll<HTMLElement>("[data-list-target]"));
    if (container.contains(previous.element)) {
      const main = previous.element
        .closest("[data-list-row]")
        ?.querySelector<HTMLElement>("[data-list-target]");
      previous.index = main ? targets.indexOf(main) : previous.index;
      return;
    }
    const active = container.ownerDocument.activeElement;
    if (
      active &&
      active !== container.ownerDocument.body &&
      active !== container.ownerDocument.documentElement
    ) {
      focusedRow.current = null;
      return;
    }
    const next = targets[Math.min(Math.max(0, previous.index), targets.length - 1)];
    focusedRow.current = null;
    (next ?? container).focus({ preventScroll: true });
  });
  const rows = rowProps(children);
  const eligible = rows
    .filter((row) => !row.disabled && row.selectable !== false)
    .map((row) => row.value);
  const count = eligible.filter((id) => selected.includes(id)).length;
  const update = (next: string[]) => {
    if (selectedIds === undefined) setOwn(next);
    onSelectionChange?.(next);
  };
  const toggle = (id: string) => {
    if (eligible.includes(id))
      update(selected.includes(id) ? selected.filter((x) => x !== id) : [...selected, id]);
  };
  const key = (event: React.KeyboardEvent<HTMLUListElement>) => {
    if (!(event.target instanceof HTMLElement) || !event.target.hasAttribute("data-list-target"))
      return;
    const targets = Array.from(
      event.currentTarget.querySelectorAll<HTMLElement>("[data-list-target]")
    );
    const index = targets.indexOf(event.target);
    let next: number | undefined;
    if (event.key === "ArrowDown") next = Math.min(targets.length - 1, index + 1);
    if (event.key === "ArrowUp") next = Math.max(0, index - 1);
    if (event.key === "Home") next = 0;
    if (event.key === "End") next = targets.length - 1;
    if (next !== undefined) {
      event.preventDefault();
      targets[next]?.focus();
    }
  };
  return (
    <FrameScope framed={inFrame || framed}>
      <ListContext
        value={{ selected, multiple: selection === "multiple", toggle, size, actionsPlacement }}
      >
        <div
          className={cn(styles.listShell, framed && frame.frame)}
          data-slot="list"
          data-frame-head={(framed && Boolean(title || headerCount || action)) || undefined}
          data-variant={variant}
          data-embedded={embedded || undefined}
          data-size={size}
        >
          {(title || headerCount || action) && (
            <div
              className={framed ? frame.frameHead : styles.listHeader}
              data-select={selection === "multiple" || undefined}
            >
              {selection === "multiple" && (
                <Checkbox
                  aria-label={`Select all ${label}`}
                  disabled={!eligible.length}
                  checked={
                    count > 0 && count < eligible.length
                      ? "indeterminate"
                      : eligible.length > 0 && count === eligible.length
                  }
                  onCheckedChange={() =>
                    update(
                      count === eligible.length
                        ? selected.filter((id) => !eligible.includes(id))
                        : [...new Set([...selected, ...eligible])]
                    )
                  }
                />
              )}
              {title && <div className={framed ? frame.frameTitle : styles.listTitle}>{title}</div>}
              {framed
                ? (headerCount || action) && (
                    <div className={frame.frameAction}>
                      {headerCount}
                      {action}
                    </div>
                  )
                : headerCount && <div className={styles.listHeaderCount}>{headerCount}</div>}
              {!framed && action && <div className={styles.listHeaderAction}>{action}</div>}
            </div>
          )}
          <ul
            ref={list}
            className={cn(styles.list, framed && frame.frameInset)}
            aria-label={label}
            aria-busy={loading}
            tabIndex={-1}
            onKeyDown={key}
            onFocusCapture={(event) => {
              if (!(event.target instanceof HTMLElement)) return;
              const row = event.target.closest("[data-list-row]");
              const main = row?.querySelector<HTMLElement>("[data-list-target]");
              if (!row || !main) {
                focusedRow.current = null;
                return;
              }
              const targets = Array.from(
                event.currentTarget.querySelectorAll<HTMLElement>("[data-list-target]")
              );
              focusedRow.current = { element: event.target, index: targets.indexOf(main) };
            }}
            onBlurCapture={(event) => {
              if (
                event.relatedTarget instanceof Node &&
                !event.currentTarget.contains(event.relatedTarget)
              )
                focusedRow.current = null;
              else if (
                !event.relatedTarget &&
                event.target instanceof HTMLElement &&
                event.target.isConnected
              )
                focusedRow.current = null;
            }}
          >
            {children}
            {loading &&
              Array.from({ length: loadingRows }, (_, index) => (
                <li key={`loading-${index}`} className={styles.listRow} aria-hidden>
                  <Skeleton />
                  <span className={styles.sr}>Loading</span>
                </li>
              ))}
            {!rows.length && !loading && <li className={styles.empty}>{empty}</li>}
          </ul>
          {footer && <div className={styles.status}>{footer}</div>}
          <span className={styles.sr} role="status">
            {selection === "multiple"
              ? `${selected.length} selected`
              : loading
                ? "Loading items"
                : ""}
          </span>
        </div>
      </ListContext>
    </FrameScope>
  );
}
export function ListSection({
  label,
  meta,
  children
}: {
  label: React.ReactNode;
  meta?: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <li>
      <div className={styles.sectionHead}>
        <div className={styles.sectionLabel}>{label}</div>
        {meta && <div className={styles.sectionMeta}>{meta}</div>}
      </div>
      <ul className={styles.list}>{children}</ul>
    </li>
  );
}
export type DataListItem =
  | readonly [React.ReactNode, React.ReactNode]
  | readonly [React.ReactNode, React.ReactNode, { span: "half" }];

const isHalf = (item?: DataListItem) => item?.[2]?.span === "half";

export function DataList({
  items,
  variant = "stat",
  density = "default"
}: {
  items: readonly DataListItem[];
  variant?: "stat" | "meta" | "props";
  density?: "default" | "compact";
}) {
  const halves = new Set<number>();
  if (density === "compact")
    items.forEach((item, index) => {
      if (halves.has(index) || !isHalf(item) || !isHalf(items[index + 1])) return;
      halves.add(index).add(index + 1);
    });
  return (
    <dl
      className={styles.dataList}
      data-slot="data-list"
      data-variant={variant}
      data-density={density}
    >
      {items.map(([term, value], index) => (
        <div
          key={index}
          className={styles.dataPair}
          data-span={halves.has(index) ? "half" : undefined}
        >
          <dt>{term}</dt>
          <dd>{value}</dd>
        </div>
      ))}
    </dl>
  );
}

.gridShell,
.tableShell,
.listShell {
  color: var(--v4-ink);
}
.gridScroll,
/* v4-check-ignore scroll-fade -- the edge fade comes from data-scroll-fade on this element */
.tableScroll {
  border-radius: 0;
  overflow: auto;
  position: relative;
}
.tableScroll {
  scroll-padding-block: var(--v4-focus-clearance);
}
.gridScroll {
  background: var(--v4-surface);
  border: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.gridScroll {
  font-family: var(--v4-type-mono-font-family);
  font-size: var(--v4-type-mono-font-size);
  line-height: var(--v4-type-mono-line-height);
  font-weight: var(--v4-type-mono-font-weight);
  letter-spacing: var(--v4-type-mono-letter-spacing);
}
.tree:focus-visible {
  outline: 2px solid var(--v4-ink);
  outline-offset: -2px;
}
.gridScroll[aria-activedescendant]:focus-visible {
  outline: none;
}
.gridRow,
.gridHead {
  display: grid;
  width: max-content;
  min-width: 100%;
}
.gridRow {
  border-bottom: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.gridRow[data-last] {
  border-bottom-color: transparent;
}
/* With a footer the grid is a framed shell: the borderless tint frame holds the inset
   grid on top and the footer below, so there is exactly one edge at the bottom. */
.gridShell[data-footer] {
  --v4-frame-pad: var(--v4-space-3);
  padding: var(--v4-frame-pad) var(--v4-frame-pad) 0;
  background: var(--v4-tint);
  border-radius: 0;
}
.gridShell[data-footer] > .gridScroll {
  border-radius: 0;
  box-shadow: var(--v4-shadow-raised);
}
.gridShell[data-footer] > .status,
.gridShell[data-footer] > .actions {
  padding-inline: var(--v4-space-8);
}
.gridFooter {
  display: flex;
  align-items: center;
  gap: var(--v4-space-12);
  min-height: var(--v4-space-40);
  padding: var(--v4-space-4) var(--v4-space-8);
  color: var(--v4-muted);
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  line-height: var(--v4-type-caption-line-height);
  font-variant-numeric: tabular-nums;
}
.gridAddHeader {
  display: flex;
  align-items: center;
  padding-inline: var(--v4-space-4);
}
.gridAddForm {
  display: grid;
  gap: var(--v4-space-6);
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
}
.gridAddCheck {
  display: flex;
  align-items: center;
  gap: var(--v4-space-8);
  margin-top: var(--v4-space-4);
}
.gridAddActions {
  display: flex;
  justify-content: flex-end;
  gap: var(--v4-space-8);
  margin-top: var(--v4-space-8);
}
.gridKey {
  flex: none;
  color: var(--v4-muted);
}
.gridHead {
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--v4-paper);
  min-height: var(--v4-size-control-sm);
  border-bottom: var(--v4-size-control-border) solid var(--v4-line-soft);
  color: var(--v4-muted);
}
.gridHeader {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0;
  border-right: var(--v4-size-control-border) solid var(--v4-line-soft);
  padding: 0 var(--v4-space-12) 0 0;
  overflow: visible;
}
.gridHeader[data-selected] {
  background: var(--v4-select);
  color: var(--v4-ink);
}
.gridHeaderLabel {
  display: flex;
  flex: 1;
  min-width: 0;
  align-items: center;
  gap: var(--v4-space-6);
  padding-inline: var(--v4-space-8);
  overflow: hidden;
}
.gridHeaderLabel > span {
  display: inline-flex;
  align-items: center;
  gap: var(--v4-space-4);
  color: var(--v4-ink);
  font-family: var(--v4-type-label-font-family);
  font-size: var(--v4-type-label-font-size);
  line-height: var(--v4-type-label-line-height);
  font-weight: var(--v4-type-label-font-weight);
  letter-spacing: var(--v4-type-label-letter-spacing);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gridHeader small {
  min-width: 0;
  overflow: hidden;
  color: var(--v4-muted);
  font-family: var(--v4-type-mono-sm-font-family);
  font-size: var(--v4-type-mono-sm-font-size);
  line-height: var(--v4-type-mono-sm-line-height);
  font-weight: var(--v4-type-mono-sm-font-weight);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gridSort[data-active] {
  color: var(--v4-ink);
}
.gridSort:not([data-active]) {
  opacity: 0;
}
.gridHeader:is(:hover, :focus-within) > .gridSort {
  opacity: 1;
}
.gutter {
  position: sticky;
  left: 0;
  z-index: 1;
  background: var(--v4-surface);
  padding: var(--v4-space-6) var(--v4-space-8);
  min-width: var(--v4-space-40);
  text-align: right;
  color: var(--v4-faint);
  border-right: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.gridHead > .gutter {
  background: inherit;
}
.gutter[data-selected] {
  background: var(--v4-select);
  color: var(--v4-ink);
}
.gutter button {
  font: inherit;
  color: inherit;
  background: none;
  border: 0;
}
.gridCell {
  padding: var(--v4-space-6) var(--v4-space-8);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  border-right: var(--v4-size-control-border) solid var(--v4-line-soft);
  position: relative;
}
:global(.v4) {
  --overlay-hover: var(--v4-hover-mix);
  --overlay-press: var(--v4-press-mix);
}
.gridRow:hover > .gridCell:not([data-selected], [data-dirty]) {
  background: color-mix(in oklab, var(--v4-mix-ink) var(--overlay-hover), transparent);
}
.gridCell[data-selected] {
  background: var(--v4-accent-wash);
}
.gridNull {
  color: var(--v4-faint);
  font-style: italic;
}
.gridCell[data-dirty] {
  background: var(--v4-warn-wash);
}
.gridCell[data-active] {
  outline: 2px solid var(--v4-ink);
  outline-offset: -2px;
}
.gridCell textarea {
  font: inherit;
  color: inherit;
  background: var(--v4-surface);
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  resize: none;
  border: 0;
  box-sizing: border-box;
  outline: 2px solid var(--v4-ink);
  outline-offset: -2px;
  padding: var(--v4-space-6) var(--v4-space-8);
  line-height: inherit;
  white-space: pre;
  overflow: hidden;
}
.gridCell textarea[aria-invalid="true"] {
  outline-color: var(--v4-bad);
}
.resize {
  position: absolute;
  top: 0;
  bottom: 0;
  right: calc(-1 * (var(--v4-space-12) + var(--v4-size-control-border)));
  z-index: 1;
  width: var(--v4-space-24);
  cursor: col-resize;
  touch-action: none;
}
.resize::after {
  content: "";
  position: absolute;
  inset-block: 0;
  left: calc(50% - var(--v4-size-control-border));
  width: var(--v4-size-control-border);
  background: transparent;
  pointer-events: none;
  transition: background-color var(--v4-duration-fast) var(--v4-ease-fade);
}
.resize:hover::after {
  background: var(--v4-control);
}
.resize:focus-visible {
  outline: 2px solid var(--v4-ink);
  outline-offset: -2px;
}
.status {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  color: var(--v4-muted);
  padding: var(--v4-space-8) 0 0;
  overflow-wrap: anywhere;
}
.actions {
  display: flex;
  align-items: center;
  gap: var(--v4-space-12);
  flex-wrap: wrap;
  padding: var(--v4-space-12) 0 0;
}
.actions [role="alert"] {
  color: var(--v4-bad);
}
.empty {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  padding: var(--v4-space-surface-inset-sm);
  color: var(--v4-muted);
}
.editor {
  display: grid;
  gap: var(--v4-space-8);
  min-width: 0;
  color: var(--v4-ink);
}
.label {
  font-family: var(--v4-type-field-label-font-family);
  font-size: var(--v4-type-field-label-font-size);
  line-height: var(--v4-type-field-label-line-height);
  font-weight: var(--v4-type-field-label-font-weight);
  letter-spacing: var(--v4-type-field-label-letter-spacing);
}
.secret {
  --v4-nested-action-height: var(--v4-size-nested-default);
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--v4-space-control-slot-gap);
  padding: var(--v4-space-control-slot-inset);
  padding-inline-start: var(--v4-space-control-inline);
  min-height: var(--v4-size-control-default);
  border: var(--v4-size-control-border) solid var(--v4-control);
  border-radius: 0;
  background: var(--v4-tint);
  min-width: 0;
}
.machine {
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
  overflow-wrap: anywhere;
  white-space: pre;
  overflow: hidden;
  text-overflow: ellipsis;
  flex: 1;
  min-width: 0;
}
.editorInput {
  display: block;
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
  border-radius: 0;
  background: var(--v4-surface);
  color: var(--v4-ink);
  border: var(--v4-size-control-border) solid var(--v4-control);
  min-height: var(--v4-size-control-default);
  max-height: calc(12 * var(--v4-type-body-line-height));
  padding: calc(
      (var(--v4-size-control-default) - var(--v4-type-body-line-height)) / 2 -
        var(--v4-size-control-border)
    )
    var(--v4-space-control-inline);
  width: 100%;
  resize: none;
  field-sizing: content;
  transition-property: border-color, box-shadow;
  transition-duration: var(--v4-duration-fast);
  transition-timing-function: var(--v4-ease-fade);
}
.editorInput:focus-visible {
  outline: none;
  border-color: var(--v4-ink);
  box-shadow: 0 0 0 var(--v4-size-focus-glow) var(--v4-focus-ring);
}
.editorInput::placeholder {
  color: var(--v4-muted);
}
.editorSlot {
  flex: none;
  width: var(--v4-nested-action-height);
  height: var(--v4-nested-action-height);
}
.editorActions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--v4-space-8);
}
.editorError {
  color: var(--v4-bad);
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  overflow-wrap: anywhere;
}
.copy {
  --v4-nested-action-height: var(--v4-size-nested-sm);
  display: inline-grid;
  align-items: center;
  gap: var(--v4-space-control-slot-gap);
  min-width: 0;
}
.copysm {
  --v4-nested-action-height: var(--v4-size-nested-sm);
}
.copymd {
  --v4-nested-action-height: var(--v4-size-nested-md);
}
.copylg {
  --v4-nested-action-height: var(--v4-size-nested-lg);
}
.secret > .copy {
  display: contents;
}
.secret > .copy > [data-copy-feedback]:not(:empty) {
  flex-basis: 100%;
}
.smallStatus {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  color: var(--v4-bad);
  overflow-wrap: anywhere;
}
/* v4-check-ignore scroll-fade -- the edge fade comes from data-scroll-fade on this element */
.tree {
  list-style: none;
  margin: 0;
  padding: 0;
  color: var(--v4-ink);
  overflow: auto;
}
.tree ul {
  list-style: none;
  margin: 0;
  padding: 0 0 0 var(--v4-space-16);
  border-left: 1px solid var(--v4-line);
}
.treeRow {
  display: flex;
  align-items: center;
  gap: var(--v4-space-8);
  min-height: var(--v4-size-control-sm);
  padding: 0 var(--v4-space-8);
  outline-offset: -2px;
  font-family: var(--v4-type-mono-font-family);
  font-size: var(--v4-type-mono-font-size);
  line-height: var(--v4-type-mono-line-height);
  font-weight: var(--v4-type-mono-font-weight);
  letter-spacing: var(--v4-type-mono-letter-spacing);
}
.tree [role="treeitem"]:focus-visible {
  outline: none;
}
.treeRow[data-size="sm"] {
  min-height: var(--v4-size-nested-md);
}
.treeRow:hover {
  background: color-mix(in oklab, var(--v4-mix-ink) var(--overlay-hover), transparent);
}
.treeRow[data-selected="true"] {
  background: var(--v4-select);
