}
.treeRow[aria-disabled="true"] {
  color: var(--v4-faint);
  cursor: not-allowed;
}
.treeName {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1;
  min-width: 0;
}
.treeMeta {
  font-family: var(--v4-type-mono-sm-font-family);
  font-size: var(--v4-type-mono-sm-font-size);
  line-height: var(--v4-type-mono-sm-line-height);
  font-weight: var(--v4-type-mono-sm-font-weight);
  letter-spacing: var(--v4-type-mono-sm-letter-spacing);
  color: var(--v4-muted);
  white-space: nowrap;
}
.listHeader {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--v4-space-12);
  padding: var(--v4-space-surface-inset-sm);
  padding-inline: calc(var(--v4-space-surface-inset-sm) + var(--v4-size-control-border));
  color: var(--v4-ink);
}
.listTitle {
  flex: 1;
  min-width: 0;
  overflow-wrap: anywhere;
  font-family: var(--v4-type-title-sm-font-family);
  font-size: var(--v4-type-title-sm-font-size);
  line-height: var(--v4-type-title-sm-line-height);
  font-weight: var(--v4-type-title-sm-font-weight);
  letter-spacing: var(--v4-type-title-sm-letter-spacing);
}
.listHeaderAction {
  margin-inline-start: auto;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  color: var(--v4-muted);
}
.listHeaderCount {
  flex: none;
  color: var(--v4-muted);
  font-variant-numeric: tabular-nums;
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  line-height: var(--v4-type-caption-line-height);
}
.listHeaderCount + .listHeaderAction {
  margin-inline-start: 0;
}
.list {
  list-style: none;
  padding: 0;
  margin: 0;
}
.listShell[data-variant="framed"] > .list,
.listShell[data-variant="plain"] > .list {
  overflow: hidden;
}
.listShell[data-variant="plain"] > .list {
  background: var(--v4-surface);
  border: var(--v4-size-control-border) solid var(--v4-line-soft);
  border-radius: 0;
}
.listShell[data-variant="framed"] > .status {
  padding: var(--v4-space-8) var(--v4-space-12) var(--v4-space-4);
}
.listShell > [data-select] {
  padding-inline-start: calc(var(--v4-space-12) + var(--v4-size-control-border));
}
.sectionHead {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--v4-space-12);
  height: var(--v4-space-32);
  padding: 0 var(--v4-space-16) var(--v4-space-6);
}
.listShell[data-size="sm"] .sectionHead {
  padding-inline: calc(var(--v4-space-16) - var(--v4-space-2));
}
.sectionLabel {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--v4-muted);
  text-transform: uppercase;
  font-family: var(--v4-type-eyebrow-font-family);
  font-size: var(--v4-type-eyebrow-font-size);
  line-height: var(--v4-type-eyebrow-line-height);
  font-weight: var(--v4-type-eyebrow-font-weight);
  letter-spacing: var(--v4-type-eyebrow-letter-spacing);
}
.sectionMeta {
  flex: none;
  color: var(--v4-muted);
  font-variant-numeric: tabular-nums;
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  line-height: var(--v4-type-caption-line-height);
}
.listShell[data-variant="bare"] .listRow {
  border-bottom-color: transparent;
}
.listShell[data-variant="segmented"] .list {
  display: grid;
  gap: var(--v4-space-4);
}
.listShell[data-variant="segmented"] > .listHeader,
.listShell[data-variant="divided"] > .listHeader,
.listShell[data-variant="segmented"] > .status,
.listShell[data-variant="divided"] > .status,
.listShell[data-variant="segmented"] .sectionHead,
.listShell[data-variant="divided"] .sectionHead {
  padding-inline: var(--v4-space-surface-inset-sm);
}
.listRow {
  display: flex;
  align-items: flex-start;
  gap: var(--v4-space-12);
  padding: var(--v4-space-surface-inset-sm);
  position: relative;
  border-bottom: var(--v4-size-control-border) solid var(--v4-line-soft);
  min-width: 0;
  --v4-list-row-surface: var(--v4-surface);
}
.rowMedia {
  position: relative;
  display: inline-flex;
  flex: none;
}
.rowMedia > .unread {
  position: absolute;
  top: calc(-1 * var(--v4-space-2));
  right: calc(-1 * var(--v4-space-2));
  box-shadow: 0 0 0 var(--v4-space-2) var(--v4-list-row-surface);
}
.listRow > .rowActions,
.listRow > .rowCheck {
  display: flex;
  align-items: center;
  height: var(--v4-type-row-title-line-height);
}
.listRow:last-child {
  border-bottom: 0;
}
:where(.listShell[data-variant="segmented"]) .listRow {
  border-bottom: 0;
  background: var(--v4-tint);
  --v4-list-row-surface: var(--v4-tint);
}
.listRow[data-selected],
.listRow[data-current] {
  background: var(--v4-selected-surface);
  --v4-list-row-surface: var(--v4-selected-surface);
}
.listRow[data-interactive] {
  transition: background-color var(--v4-duration-fast) var(--v4-ease-fade);
}
.listRow[data-interactive]:not([data-selected], [data-current]):hover {
  background: color-mix(in oklab, var(--v4-mix-ink) var(--overlay-hover), transparent);
  --v4-list-row-surface: color-mix(
    in oklab,
    var(--v4-mix-ink) var(--overlay-hover),
    var(--v4-surface)
  );
}
:where(.listShell[data-variant="segmented"])
  .listRow[data-interactive]:not([data-selected], [data-current]):hover {
  background: color-mix(in oklab, var(--v4-mix-ink) var(--overlay-hover), var(--v4-tint));
  --v4-list-row-surface: color-mix(
    in oklab,
    var(--v4-mix-ink) var(--overlay-hover),
    var(--v4-tint)
  );
}
.listRow[data-interactive][data-pressed]:not([data-selected], [data-current]) {
  background: color-mix(in oklab, var(--v4-mix-ink) var(--overlay-press), transparent);
}
:where(.listShell[data-variant="segmented"])
  .listRow[data-interactive][data-pressed]:not([data-selected], [data-current]) {
  background: color-mix(in oklab, var(--v4-mix-ink) var(--overlay-press), var(--v4-tint));
}
.listRow[data-resolved] {
  background: var(--v4-row-done);
  --v4-list-row-surface: var(--v4-row-done);
  color: var(--v4-muted);
}
:where(.listShell[data-variant="segmented"]) .listRow[data-resolved] {
  background: var(--v4-row-done-card);
  --v4-list-row-surface: var(--v4-row-done-card);
}
:where(.listShell[data-variant="divided"]) .listRow[data-resolved] {
  background: var(--v4-row-done-divided);
  --v4-list-row-surface: var(--v4-row-done-divided);
}
.listRow[data-disabled] {
  color: var(--v4-muted);
}
.listRow[data-size="sm"] {
  padding: var(--v4-space-8) var(--v4-space-surface-inset-sm);
  min-height: var(--v4-space-40);
}
.listBody {
  flex: 1;
  min-width: 0;
  display: grid;
  gap: var(--v4-space-4);
}
.listBody > .rowActions {
  padding-top: calc(var(--v4-space-actions-gap) - var(--v4-space-4));
}
.titleLine {
  display: flex;
  align-items: center;
  gap: var(--v4-space-8);
  min-width: 0;
}
.titleLine > .rowTitle {
  flex: 0 1 auto;
}
.rowTitle {
  color: inherit;
  font-family: var(--v4-type-row-title-font-family);
  font-size: var(--v4-type-row-title-font-size);
  line-height: var(--v4-type-row-title-line-height);
  font-weight: var(--v4-type-row-title-font-weight);
  letter-spacing: var(--v4-type-row-title-letter-spacing);
  text-decoration: none;
  background: none;
  border: 0;
  padding: 0;
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
  cursor: inherit;
}
/* v4-check-ignore cursor-pointer -- a List title button opens its item like the anchor title beside it, so it reads as a link */
a.rowTitle,
button.rowTitle {
  cursor: pointer;
}
a.rowTitle::after,
button.rowTitle::after {
  content: "";
  position: absolute;
  inset: 0;
}
.rowTitle:focus-visible {
  outline: 0;
}
.rowMeta {
  flex: none;
  align-self: flex-start;
  margin-left: auto;
  white-space: nowrap;
  color: var(--v4-muted);
  font-family: var(--v4-type-mono-sm-font-family);
  font-size: var(--v4-type-mono-sm-font-size);
  line-height: var(--v4-type-row-title-line-height);
  font-weight: var(--v4-type-mono-sm-font-weight);
  letter-spacing: var(--v4-type-mono-sm-letter-spacing);
}
.rowActions {
  display: flex;
  gap: var(--v4-space-8);
  position: relative;
  z-index: 1;
  flex-wrap: wrap;
}
.rowCheck,
.rowBadge {
  position: relative;
  z-index: 1;
  flex-shrink: 0;
}
.description {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  color: var(--v4-muted);
  margin: 0;
  overflow-wrap: anywhere;
}
.rowError {
  color: var(--v4-bad);
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.unread {
  width: var(--v4-space-6);
  height: var(--v4-space-6);
  background: var(--v4-accent-fg);
  border-radius: 0;
  flex-shrink: 0;
}
.tableToggle {
  display: inline-flex;
  align-items: center;
  vertical-align: middle;
}
.tableToggle + * {
  margin-inline-start: var(--v4-space-8);
}
.tableToggleCell {
  display: flex;
  align-items: center;
  gap: var(--v4-space-4);
  min-height: var(--v4-size-target-row);
}
.tableToggleCell > .tableToggle + * {
  margin-inline-start: 0;
}
.tableToggleAbsent {
  display: flex;
  min-height: var(--v4-size-target-row);
  align-items: center;
  justify-content: center;
  width: var(--v4-size-icon-lg);
  color: var(--v4-faint);
}
.sr {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
.dataList {
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
  display: grid;
  gap: var(--v4-space-12);
  margin: 0;
}
.dataPair {
  align-items: center;
  display: flex;
  gap: var(--v4-space-12);
  justify-content: space-between;
  border-bottom: var(--v4-size-control-border) solid var(--v4-line-soft);
  padding: var(--v4-space-8) 0;
}
.dataPair dt {
  color: var(--v4-muted);
  min-width: min-content;
  max-width: 45%;
}
.dataPair dd {
  margin: 0;
  min-width: 0;
  overflow-wrap: anywhere;
  text-align: right;
}
.dataList[data-density="compact"] {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  column-gap: var(--v4-space-16);
  row-gap: 0;
}
.dataList[data-density="compact"] .dataPair {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: minmax(min-content, var(--v4-size-data-list-term)) minmax(0, 1fr);
  align-content: center;
  align-items: baseline;
  gap: 0 var(--v4-space-12);
  min-height: var(--v4-size-data-list-row);
  padding: var(--v4-space-4) 0;
}
.dataList[data-density="compact"] .dataPair[data-span="half"] {
  grid-column: auto;
  grid-template-columns: minmax(0, 1fr);
  align-content: start;
}
.dataList[data-density="compact"] dt {
  max-width: none;
}
.dataList[data-density="compact"] dd {
  text-align: start;
}
.dataList[data-variant="stat"] dd {
  font-family: var(--v4-type-display-font-family);
  font-size: var(--v4-type-display-font-size);
  line-height: var(--v4-type-display-line-height);
  font-weight: var(--v4-type-display-font-weight);
  letter-spacing: var(--v4-type-display-letter-spacing);
  font-variant-numeric: tabular-nums;
}
@media (max-width: 480px) {
  .listRow {
    flex-wrap: wrap;
  }
  .rowActions {
    width: 100%;
  }
}
.tableScroll .nativeTableContainer {
  overflow: visible;
}
.tableScroll table {
  border-collapse: separate;
  border-spacing: 0;
  min-width: 100%;
}
.tableShell > .tableScroll {
  padding-top: 0;
}
/* Sticky at the inline start so a horizontally scrolled table keeps the control centered in view. */
.tableMore {
  position: sticky;
  inset-inline-start: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.nativeTableRow:is(:focus, :focus-visible) {
  outline: none;
}
.tree [role="treeitem"]:focus-visible > .treeRow {
  position: relative;
}
/* One row focus ring: an overlay inside the row box, above pinned cells and clear of neighbouring rows' borders. */
.tree [role="treeitem"]:focus-visible > .treeRow::after,
.rowTitle:focus-visible::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 6;
  border: var(--v4-size-focus-ring) solid var(--v4-ink);
  pointer-events: none;
}
/* A table row draws the same ring from its cells: a box on the tr itself becomes an extra column in table layout. Zero specificity keeps pinned cells sticky. */
:where(.nativeTableRow[data-focus-ring]) > :where(td, th) {
  position: relative;
  isolation: isolate;
}
.nativeTableRow[data-focus-ring] > :is(td, th)::after {
  content: "";
  position: absolute;
  inset-block: 0;
  inset-inline: 0 calc(-1 * var(--v4-size-control-border));
  z-index: 6;
