  height: var(--v4-size-target-row);
}
.tableRowIndicators svg {
  width: var(--v4-size-glyph);
  height: var(--v4-size-glyph);
}

/* v4-check-ignore scroll-fade -- the edge fade comes from data-scroll-fade on this element */
.nativeTableContainer {
  overflow-x: auto;
}

.secret[data-multiline] .machine {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.rowBadge {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}

.copy > :global(button) {
  max-width: 100%;
  white-space: normal;
  overflow-wrap: anywhere;
}

.frame {
  --v4-frame-pad: var(--v4-space-3);
  --v4-frame-inner-radius: 0;
  min-width: 0;
  padding: var(--v4-frame-pad);
  background: var(--v4-tint);
  border: 0;
  border-radius: 0;
}
.frame[data-frame-head] {
  padding-top: 0;
}
.frame[data-frame-foot] {
  padding-bottom: 0;
}
.frameFoot.frameFoot {
  min-height: var(--v4-space-40);
  padding: var(--v4-space-8) var(--v4-space-12);
  border: 0;
  color: var(--v4-muted);
  font-variant-numeric: tabular-nums;
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  line-height: var(--v4-type-caption-line-height);
}
.frameHead {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  align-content: center;
  justify-content: space-between;
  gap: var(--v4-space-4) var(--v4-space-12);
  min-height: var(--v4-space-40);
  padding: var(--v4-space-4) var(--v4-space-12);
  min-width: 0;
}
.frameTitle {
  flex: 1 1 var(--v4-size-cell-min);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--v4-muted);
  text-transform: uppercase;
  font-family: var(--v4-type-eyebrow-font-family);
  font-size: var(--v4-type-eyebrow-font-size);
  line-height: var(--v4-type-eyebrow-line-height);
  font-weight: var(--v4-type-eyebrow-font-weight);
  letter-spacing: var(--v4-type-eyebrow-letter-spacing);
}
.frameAction {
  flex: none;
  margin-inline-start: 0;
  display: flex;
  align-items: center;
  gap: var(--v4-space-8);
  color: var(--v4-text2);
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  line-height: var(--v4-type-caption-line-height);
  font-weight: var(--v4-type-label-font-weight);
}
.frameAction > a:not([data-slot]) {
  color: var(--v4-link);
  text-decoration: underline;
  text-decoration-thickness: var(--v4-size-control-border);
  text-underline-offset: var(--v4-space-3);
}
.frameAction > a:not([data-slot]):hover {
  color: var(--v4-text2);
  text-decoration-thickness: var(--v4-space-2);
}
.frameInset {
  min-width: 0;
  background: var(--v4-surface);
  border: var(--v4-size-control-border) solid var(--v4-line-soft);
  border-radius: var(--v4-frame-inner-radius);
  box-shadow: var(--v4-shadow-raised);
}
